-- =============================================================================
-- seed.sql — SoftWinQuote catalog seed data (scraped from the live original)
-- =============================================================================
-- HOW TO USE:
--   1. Set :owner below to YOUR Supabase auth user id (from auth.users).
--      Find it: SELECT id, email FROM auth.users;
--   2. Run this whole file in the Supabase SQL Editor.
-- All catalog rows are owned by that user (created_by) so RLS lets you see them.
-- Re-running is safe-ish: it DELETEs this owner's existing catalog rows first.
-- =============================================================================

DO $$
DECLARE
  owner UUID;
BEGIN
  -- >>> EDIT THIS: pick your user. Defaults to the first profile. <<<
  SELECT id INTO owner FROM public.profiles ORDER BY created_at LIMIT 1;
  IF owner IS NULL THEN
    RAISE EXCEPTION 'No profile found. Create a user first, then re-run.';
  END IF;

  -- Clean this owner's existing catalog rows so the seed is idempotent.
  DELETE FROM public.series_profiles    WHERE created_by = owner;
  DELETE FROM public.design_accessories WHERE created_by = owner;
  DELETE FROM public.design_glasses     WHERE created_by = owner;
  DELETE FROM public.design_colors      WHERE created_by = owner;
  DELETE FROM public.aluminium_series   WHERE created_by = owner;

  -- ---- Glass + mesh options (design_glasses) ----

  -- ---- Hardware / accessories (design_accessories) ----
  -- original type -> our kind: handle->handle, hinges->hinge, roller->roller,
  --   friction->friction_stay, mesh_component->mesh, lock->lock, common->common

  -- ---- Profile Company + Series registry (aluminium_series) ----
  -- company + series + available_length + external_id (API series id).
  -- Insert each series and capture its new UUID into a temp map via a CTE-less
  -- approach: we insert then look up by (created_by, external_id) when seeding profiles.

  -- ---- Series-scoped profiles (series_profiles) ----
  -- Each row attaches to its series by looking up external_id for this owner.

  -- ---- Colours (design_colors) ----

  -- ---- Aluminium cost settings (per-user, single row) ----
    user_id, aluminium_rate, profit_percentage, labour_charge, coating,
    corner_cleat, weather_strip, ss_corner_con, screw, rail, fastner,
    dustpad, outer_clit, sash_clit, l_pati, lockguide_cap, interlock_cap,
    bubstopper, ugid, lockguid, water_drainage, brassrubber, suitbelt,
    slider_width_overlap, slider_height_overlap, slider_glass_overlap, slim_width_overlap,
    casement_width_overlap, casement_height_overlap, casement_glass_overlap
  ) VALUES (
    owner, 500, 0, 40, 0,
    30, 50, 50, 2, 100, 5,
    10, 30, 30, 6, 10, 15,
    25, 8, 8, 10, 6, 0,
    25, 18, 16, 25,
    12, 12, 20
  )
  ON CONFLICT (user_id) DO UPDATE SET
    aluminium_rate = EXCLUDED.aluminium_rate,
    profit_percentage = EXCLUDED.profit_percentage,
    labour_charge = EXCLUDED.labour_charge,
    coating = EXCLUDED.coating,
    corner_cleat = EXCLUDED.corner_cleat,
    weather_strip = EXCLUDED.weather_strip,
    ss_corner_con = EXCLUDED.ss_corner_con,
    screw = EXCLUDED.screw,
    rail = EXCLUDED.rail,
    fastner = EXCLUDED.fastner,
    dustpad = EXCLUDED.dustpad,
    outer_clit = EXCLUDED.outer_clit,
    sash_clit = EXCLUDED.sash_clit,
    l_pati = EXCLUDED.l_pati,
    lockguide_cap = EXCLUDED.lockguide_cap,
    interlock_cap = EXCLUDED.interlock_cap,
    bubstopper = EXCLUDED.bubstopper,
    ugid = EXCLUDED.ugid,
    lockguid = EXCLUDED.lockguid,
    water_drainage = EXCLUDED.water_drainage,
    brassrubber = EXCLUDED.brassrubber,
    suitbelt = EXCLUDED.suitbelt,
    slim_width_overlap = EXCLUDED.slim_width_overlap;

  RAISE NOTICE 'Seed complete for owner %', owner;
END $$;
